import{_ as t,o as n,c as s,ah as e}from"./chunks/framework.Yx0DUrwu.js";const g=JSON.parse('{"title":"AnnData 教程","description":"","frontmatter":{},"headers":[],"relativePath":"tools/anndata/index.md","filePath":"tools/anndata/index.md","lastUpdated":1787828101000}'),o={name:"tools/anndata/index.md"};function r(i,a,l,d,c,p){return n(),s("div",null,[...a[0]||(a[0]=[e('<h1 id="anndata-教程" tabindex="-1">AnnData 教程 <a class="header-anchor" href="#anndata-教程" aria-label="Permalink to &quot;AnnData 教程&quot;">​</a></h1><p>AnnData 是 Python/scverse 生态里的核心数据容器。Scanpy、scvi-tools、Squidpy、Muon 等工具能顺畅协作，很大程度上是因为它们围绕 AnnData 或 AnnData-like 对象组织数据。</p><p>官方 getting started 教程强调两个事实：AnnData 本质上是一个带注释的矩阵，行通常是 observations/cells，列通常是 variables/genes；表达矩阵和元数据、降维结果、图结构、非结构化结果会被放在固定字段里。实践中，先学 AnnData 会比直接背 Scanpy 函数更稳。</p><div class="scanpy-panel"><div><span class="eyebrow">AnnData first</span><h2>先理解容器，再理解流程</h2><p>单细胞分析里很多“结果去哪了”的问题，本质都是 AnnData 字段问题。QC 指标通常进 obs，基因统计进 var，UMAP 坐标进 obsm，marker gene 排名进 uns，原始 counts 可存 layers。</p></div><div class="metrics"><span>主矩阵 <strong>adata.X</strong></span><span>细胞表 <strong>adata.obs</strong></span><span>基因表 <strong>adata.var</strong></span><span>多矩阵 <strong>adata.layers</strong></span><span>低维坐标 <strong>adata.obsm</strong></span></div></div><h2 id="推荐阅读顺序" tabindex="-1">推荐阅读顺序 <a class="header-anchor" href="#推荐阅读顺序" aria-label="Permalink to &quot;推荐阅读顺序&quot;">​</a></h2><div class="path-grid"><a href="/tools/anndata/object-structure-io"><strong>对象结构与读写</strong><span>理解 X, obs, var, layers, raw, obsm, varm, obsp, and uns，并学会保存 h5ad。</span></a><a href="/tools/scanpy/"><strong>Scanpy 教程</strong><span>把 AnnData 放入真实分析流程，看每一步结果写入哪些字段。</span></a><a href="/tools/scvi-tools/"><strong>scvi-tools 教程</strong><span>理解 scvi-tools 为什么要求保留 raw counts 和 batch/covariate metadata。</span></a><a href="/practice/raw-matrix-to-report"><strong>实战模板</strong><span>查看本地 pipeline 如何在 layers, obs, obsm, and uns 之间保存结果。</span></a></div><h2 id="实践判断" tabindex="-1">实践判断 <a class="header-anchor" href="#实践判断" aria-label="Permalink to &quot;实践判断&quot;">​</a></h2><div class="doc-callout important"><strong>不要随意覆盖 counts</strong><p>许多统计模型和整合方法需要原始 counts。常见做法是把 counts 存在 <code>adata.layers[&quot;counts&quot;]</code>，把归一化/log 转换后的矩阵用于常规可视化。</p></div><h2 id="资料来源" tabindex="-1">资料来源 <a class="header-anchor" href="#资料来源" aria-label="Permalink to &quot;资料来源&quot;">​</a></h2><ul><li><a href="https://anndata.readthedocs.io/" target="_blank" rel="noreferrer">AnnData official documentation</a></li><li><a href="https://anndata.readthedocs.io/en/stable/tutorials/notebooks/getting-started.html" target="_blank" rel="noreferrer">AnnData getting started tutorial</a></li><li><a href="https://scverse.org/" target="_blank" rel="noreferrer">scverse ecosystem</a></li></ul>',10)])])}const u=t(o,[["render",r]]);export{g as __pageData,u as default};
